const $=s=>document.querySelector(s), chatEl=$("#chat"),messagesEl=$("#messages"),input=$("#input"),send=$("#send"),drawer=$("#drawer"),scrim=$("#scrim"),drawerBody=$("#drawerBody");
let currentId=null,me=null,history=[],busy=false,attached=[],toastTimer;

/* Animated particle field for the boot screen */
function startMiaBoot(){const layer=$("#miaBoot"),canvas=$("#miaParticles");if(!layer||!canvas)return()=>{};const ctx=canvas.getContext("2d");if(!ctx)return()=>{};let w=0,h=0,raf=0,points=[],dpr=1,alive=true;const reduce=window.matchMedia("(prefers-reduced-motion: reduce)").matches;
function resize(){dpr=Math.min(window.devicePixelRatio||1,1.5);w=innerWidth;h=innerHeight;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);const count=Math.min(175,Math.max(60,Math.round(w*h/8000)));points=Array.from({length:count},()=>({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-.5)*.28,vy:(Math.random()-.5)*.28,r:Math.random()*1.5+.35,a:Math.random()*.55+.2,p:Math.random()*6.28}))}
function draw(){if(!alive)return;ctx.clearRect(0,0,w,h);const max=reduce?0:168;for(let i=0;i<points.length;i++){const p=points[i];if(!reduce){p.x+=p.vx;p.y+=p.vy;p.p+=.012;if(p.x<0||p.x>w)p.vx*=-1;if(p.y<0||p.y>h)p.vy*=-1}const alpha=p.a*(.72+.28*Math.sin(p.p));ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle="rgba(224,204,255,"+Math.min(1,alpha*1.48)+")";ctx.fill();if(max)for(let j=i+1;j<points.length;j++){const q=points[j],dx=p.x-q.x,dy=p.y-q.y,dist=Math.hypot(dx,dy);if(dist<max){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle="rgba(194,158,255,"+((1-dist/max)*.34)+")";ctx.lineWidth=.7;ctx.stroke()}}}if(!reduce)raf=requestAnimationFrame(draw)}
resize();window.addEventListener("resize",resize);if(reduce)draw();else raf=requestAnimationFrame(draw);return()=>{alive=false;cancelAnimationFrame(raf);window.removeEventListener("resize",resize)}}
const miaBootStartedAt=performance.now();
const stopMiaBoot=startMiaBoot();
function startAmbientNetwork(host,{count=34,reach=115,speed=.32,opacity=.72,size=1.25}={}){
 if(!host||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return()=>{};
 const canvas=document.createElement("canvas");canvas.className="mia-network-canvas";canvas.setAttribute("aria-hidden","true");host.prepend(canvas);
 const ctx=canvas.getContext("2d");if(!ctx)return()=>{};
 let w=0,h=0,dpr=1,pts=[],raf=0,alive=true;
 function resize(){const r=host.getBoundingClientRect();w=Math.max(1,r.width);h=Math.max(1,r.height);dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvas.style.width=w+"px";canvas.style.height=h+"px";ctx.setTransform(dpr,0,0,dpr,0,0);pts=Array.from({length:count},()=>({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-.5)*speed,vy:(Math.random()-.5)*speed,r:Math.random()*size+.55,phase:Math.random()*6.28}))}
 function frame(){if(!alive)return;ctx.clearRect(0,0,w,h);for(let i=0;i<pts.length;i++){const p=pts[i];p.x+=p.vx;p.y+=p.vy;p.phase+=.025;if(p.x<0||p.x>w)p.vx*=-1;if(p.y<0||p.y>h)p.vy*=-1;const pulse=.65+.35*Math.sin(p.phase);ctx.beginPath();ctx.arc(p.x,p.y,p.r*(.8+pulse*.35),0,Math.PI*2);ctx.fillStyle="rgba(226,204,255,"+(opacity*pulse)+")";ctx.shadowBlur=9;ctx.shadowColor="#c59aff";ctx.fill();ctx.shadowBlur=0;for(let j=i+1;j<pts.length;j++){const q=pts[j],dx=p.x-q.x,dy=p.y-q.y,d=Math.hypot(dx,dy);if(d<reach){const a=(1-d/reach)*opacity*.48;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle="rgba(185,143,255,"+a+")";ctx.lineWidth=.7;ctx.stroke()}}}raf=requestAnimationFrame(frame)}
 const ro=new ResizeObserver(resize);ro.observe(host);resize();raf=requestAnimationFrame(frame);
 return()=>{alive=false;cancelAnimationFrame(raf);ro.disconnect();canvas.remove()};
}
const stopAmbient=[
 startAmbientNetwork(document.querySelector(".main"),{count:112,reach:176,speed:.62,opacity:.78,size:1.45}),


];
function finishMiaBoot(){const layer=$("#miaBoot");if(!layer)return;const wait=Math.max(0,5000-(performance.now()-miaBootStartedAt));setTimeout(()=>{layer.classList.add("is-leaving");setTimeout(()=>{stopMiaBoot();layer.remove()},850)},wait)}

const localKey="mia-v2-guest-chats";
function toast(s){$("#toast").textContent=translateValue(s);$("#toast").classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("#toast").classList.remove("show"),2500)}
async function api(path,opts={}){const r=await fetch("/api"+path,{credentials:"include",headers:{"Content-Type":"application/json",...(opts.headers||{})},...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||"Có lỗi xảy ra");return d}
function guestLoad(){try{return JSON.parse(localStorage.getItem(localKey)||"[]")}catch{return []}}
function guestSave(){localStorage.setItem(localKey,JSON.stringify(history))}
function id(){return "g_"+Math.random().toString(36).slice(2)+Date.now().toString(36)}
function openDrawer(title,body){$("#drawerTitle").textContent=title;drawerBody.innerHTML="";drawerBody.append(body);drawer.classList.add("open");scrim.classList.add("open");drawer.setAttribute("aria-hidden","false");document.body.classList.add("drawer-open")}
function closeDrawer(){drawer.classList.remove("open");scrim.classList.remove("open");drawer.setAttribute("aria-hidden","true");document.body.classList.remove("drawer-open")}
$("#closeDrawer").onclick=closeDrawer;scrim.onclick=closeDrawer;
function newChat(){currentId=null;messagesEl.innerHTML="";$("#welcome").style.display="flex";input.focus();closeDrawer()}
$("#newChat").onclick=newChat;$("#home").onclick=newChat;
function fmt(t){return new Date(t||Date.now()).toLocaleDateString("vi-VN",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"})}
function localConversation(){let c=history.find(x=>x.id===currentId);if(!c){c={id:currentId||id(),title:"Cuộc trò chuyện mới",updatedAt:Date.now(),messages:[]};history.unshift(c);currentId=c.id}return c}
function renderHistory(){const box=document.createElement("div");let btn=document.createElement("button");btn.className="draweraction";btn.textContent="⊕ Cuộc trò chuyện mới";btn.onclick=newChat;box.append(btn);if(!history.length){let p=document.createElement("p");p.className="mutedtext";p.textContent="Chưa có cuộc trò chuyện nào.";box.append(p)}history.forEach(c=>{let row=document.createElement("div");row.className="historyitem";row.innerHTML='<span class="historymark">✦</span><span class="htitle"></span><small></small><button class="historydelete" title="Xóa">⊗</button>';row.querySelector(".htitle").textContent=c.title||"Cuộc trò chuyện";row.querySelector("small").textContent=fmt(c.updatedAt);let rename=document.createElement("button");rename.className="historyrename";rename.title="Đổi tên";rename.textContent="✎";rename.onclick=async e=>{e.stopPropagation();let title=prompt(translateValue("Tên cuộc trò chuyện mới:"),c.title||translateValue("Cuộc trò chuyện"));if(title===null)return;title=title.trim();if(!title)return toast("Tên không được để trống");try{if(me&&!me.guest)await api("/conversations/"+c.id,{method:"PATCH",body:JSON.stringify({title})});c.title=title.slice(0,100);if(!me||me.guest)guestSave();renderHistory();toast("Đã đổi tên")}catch(err){toast(err.message)}};row.append(rename);row.onclick=()=>loadConversation(c.id);row.querySelector(".historydelete").onclick=async e=>{e.stopPropagation();if(!confirm(translateValue("Xóa cuộc trò chuyện này?")))return;try{if(me&&!me.guest)await api("/conversations/"+c.id,{method:"DELETE"});history=history.filter(x=>x.id!==c.id);guestSave();if(currentId===c.id)newChat();renderHistory();toast("Đã xóa cuộc trò chuyện")}catch(err){toast(err.message)}};box.append(row)});openDrawer("Lịch sử",box)}
$("#openHistory").onclick=renderHistory;$("#accountBtn").addEventListener("click",e=>{e.preventDefault();e.stopPropagation();account()});$("#headerHistory")?.addEventListener("click",renderHistory);

