for(const [lang,dict] of Object.entries(EXTRA_TRANSLATIONS))Object.assign(I18N[lang],dict);
let currentLanguage="vi";
const originalTextNodes=new WeakMap(),originalAttributes=new WeakMap();
function translateValue(value){const dict=I18N[currentLanguage]||{};const key=String(value||"").trim();if(dict[key])return dict[key];let out=key;for(const [from,to] of Object.entries(dict).sort((a,b)=>b[0].length-a[0].length)){if(out.includes(from))out=out.split(from).join(to)}return out}
function applyLanguage(root=document.body){if(!root)return;document.documentElement.lang=currentLanguage;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest("script,style,textarea,code"))continue;if(!originalTextNodes.has(node))originalTextNodes.set(node,node.nodeValue);const original=originalTextNodes.get(node),trim=original.trim();if(!trim)continue;const translated=translateValue(trim);node.nodeValue=original.replace(trim,translated)}root.querySelectorAll?.("[placeholder],[title],[aria-label]").forEach(el=>["placeholder","title","aria-label"].forEach(a=>{if(!el.hasAttribute(a))return;let saved=originalAttributes.get(el);if(!saved){saved={};originalAttributes.set(el,saved)}if(!(a in saved))saved[a]=el.getAttribute(a);el.setAttribute(a,translateValue(saved[a]))}))}

function setLanguage(code,manual=true){if(!LANGS.some(x=>x[0]===code))return;currentLanguage=code;if(manual)localStorage.setItem("mia-language",code);applyLanguage();toast(translateValue("Đã cập nhật ngôn ngữ"))}
function language(){const box=document.createElement("div");const p=document.createElement("p");p.className="mutedtext";p.textContent=translateValue("Chọn ngôn ngữ hiển thị");box.append(p);LANGS.forEach(([code,flag,name])=>{const b=document.createElement("button");b.className="draweraction language-option"+(currentLanguage===code?" selected":"");const labels={"vi":["Việt","Nhật","Hàn","Trung","Anh","Mỹ"],"ja":["ベトナム語","日本語","韓国語","中国語","英語（英国）","英語（米国）"],"ko":["베트남어","일본어","한국어","중국어","영국 영어","미국 영어"],"zh":["越南语","日语","韩语","中文","英式英语","美式英语"],"en-GB":["Vietnamese","Japanese","Korean","Chinese","English (UK)","English (US)"],"en-US":["Vietnamese","Japanese","Korean","Chinese","English (UK)","English (US)"]};b.textContent=flag+"  "+(labels[currentLanguage]||labels.vi)[LANGS.findIndex(x=>x[0]===code)];b.onclick=()=>{setLanguage(code,true);language()};box.append(b)});openDrawer(translateValue("Ngôn ngữ"),box)}
async function initLanguage(){const saved=localStorage.getItem("mia-language");let country="";if(saved&&LANGS.some(x=>x[0]===saved)){currentLanguage=saved}else{try{const cfg=await api("/config");country=String(cfg.country||"").toUpperCase()}catch{}if(!country){try{const geo=await fetch("https://ipapi.co/json/");if(geo.ok){const data=await geo.json();country=String(data.country_code||"").toUpperCase()}}catch{}}const byCountry={"VN":"vi","JP":"ja","KR":"ko","CN":"zh","TW":"zh","HK":"zh","US":"en-US","GB":"en-GB","IE":"en-GB","AU":"en-GB","NZ":"en-GB"};const byLocale=(navigator.language||"").toLowerCase();currentLanguage=byCountry[country]||(["ja","ko","zh"].includes(byLocale.slice(0,2))?byLocale.slice(0,2):byLocale==="en-us"?"en-US":byLocale.startsWith("en")?"en-GB":"vi")}applyLanguage();const observer=new MutationObserver(records=>records.forEach(r=>{r.addedNodes.forEach(n=>{if(n.nodeType===Node.ELEMENT_NODE)applyLanguage(n);else if(n.nodeType===Node.TEXT_NODE){if(!originalTextNodes.has(n))originalTextNodes.set(n,n.nodeValue);const original=originalTextNodes.get(n),v=original?.trim(),t=translateValue(v);if(v)n.nodeValue=original.replace(v,t)}})}));observer.observe(document.body,{childList:true,subtree:true})}

function menu(){if(drawer.classList.contains("open")&&$("#drawerTitle").textContent==="Menu"){closeDrawer();return}let box=document.createElement("div");const actions=[["⊕  Chat mới",newChat],["❖  Lịch sử",renderHistory],["✦  Giao diện · Tạm khóa",()=>toast("Tùy chỉnh giao diện đang được tạm khóa.") ,true],["♪  Nhạc nền",music],["文  Ngôn ngữ",language],["ⓘ  Về Mia",about],["♡  Đăng nhập / Tài khoản",account]];actions.forEach(([t,f,locked])=>{let b=document.createElement("button");b.className="draweraction"+(locked?" is-locked":"");b.textContent=t;if(locked){b.disabled=true;b.title="Tính năng đang tạm khóa"}else b.onclick=f;box.append(b)});openDrawer("Menu",box)}
$("#openMenu").onclick=menu;$("#headerMenu")?.addEventListener("click",menu);
function settings(){let box=document.createElement("div");box.innerHTML='<label class="fieldlabel">Chủ đề</label><select class="field" id="theme"><option value="dark">Dark</option><option value="light">Light</option><option value="custom">Custom</option></select><label class="fieldlabel">Màu nhấn</label><input class="field" type="color" id="accent" value="#c4a4ff"><label class="fieldlabel">Nền giao diện (Custom)</label><input class="field" type="color" id="bgcolor" value="#101114"><label class="fieldlabel">Nền bảng (Custom)</label><input class="field" type="color" id="panelcolor" value="#17161b"><label class="fieldlabel">Nền chat (ảnh)</label><input class="field" type="file" id="wall" accept="image/*"><label class="fieldlabel">Nền chat (video, phiên hiện tại)</label><input class="field" type="file" id="wallvideo" accept="video/*"><button class="draweraction" id="clearwall">Xóa nền chat</button>';openDrawer("Giao diện",box);$("#theme").value=localStorage.theme||"dark";$("#accent").value=localStorage.accent||"#c4a4ff";$("#bgcolor").value=localStorage.bgcolor||"#101114";$("#panelcolor").value=localStorage.panelcolor||"#17161b";$("#theme").onchange=e=>{localStorage.theme=e.target.value;applyTheme()};$("#accent").oninput=e=>{localStorage.accent=e.target.value;applyTheme()};$("#bgcolor").oninput=e=>{localStorage.bgcolor=e.target.value;applyTheme()};$("#panelcolor").oninput=e=>{localStorage.panelcolor=e.target.value;applyTheme()};$("#wallvideo").onchange=e=>{let f=e.target.files[0];if(!f)return;if(f.size>30e6)return toast("Video nền tối đa 30 MB");let old=$("#chatwallvideo");if(old)old.remove();let v=document.createElement("video");v.id="chatwallvideo";v.src=URL.createObjectURL(f);v.autoplay=true;v.loop=true;v.muted=true;v.playsInline=true;v.style.cssText="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.22;pointer-events:none;z-index:0";chatEl.prepend(v);messagesEl.style.position="relative";toast("Đã bật video nền cho phiên này")};$("#wall").onchange=e=>{let f=e.target.files[0];if(!f)return;if(f.size>4e6)return toast("Ảnh nền tối đa 4 MB");let rd=new FileReader();rd.onload=()=>{localStorage.wall=rd.result;applyWall()};rd.readAsDataURL(f)};$("#clearwall").onclick=()=>{localStorage.removeItem("wall");applyWall();toast("Đã xóa nền")}}
function applyTheme(){let t=localStorage.theme||"dark",root=document.documentElement;if(t==="light"){root.style.setProperty("--bg","#f6f4f8");root.style.setProperty("--panel","#fff");root.style.setProperty("--surface","#efedf2");root.style.setProperty("--text","#211d27");root.style.setProperty("--muted","#77717e");root.style.setProperty("--line","#e3dfe8");root.style.setProperty("--user","#eae4f1")}else{root.style.setProperty("--bg",t==="custom"?(localStorage.bgcolor||"#101114"):"#101114");root.style.setProperty("--panel",t==="custom"?(localStorage.panelcolor||"#17161b"):"#17161b");root.style.setProperty("--surface","#211f25");root.style.setProperty("--text","#f3f0f6");root.style.setProperty("--muted","#9b96a3");root.style.setProperty("--line","#302d35");root.style.setProperty("--user","#29252f")}root.style.setProperty("--accent",localStorage.accent||"#c4a4ff")}
function applyWall(){const target=document.querySelector(".main");target.style.backgroundImage=localStorage.wall?'linear-gradient(135deg,#101014a8,#101014b8),url('+localStorage.wall+')':'none';target.style.backgroundSize="cover";target.style.backgroundPosition="center";chatEl.style.backgroundImage="none"}
function musicStore(mode,blob){return new Promise((resolve,reject)=>{let q=indexedDB.open("mia-media",1);q.onupgradeneeded=()=>q.result.createObjectStore("files");q.onerror=()=>reject(q.error);q.onsuccess=()=>{let db=q.result,tx=db.transaction("files",mode==="put"?"readwrite":"readonly"),st=tx.objectStore("files"),req=mode==="put"?st.put(blob,"music"):st.get("music");req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}})}
function music(){let box=document.createElement("div");box.innerHTML='<p class="mutedtext">Trình duyệt cần thao tác của cậu để phát âm thanh. Chọn file nhạc từ thiết bị nhé.</p><label class="fieldlabel">File nhạc: <span id="musicName">[Tệp Nhạc]</span></label><input class="field" id="audiofile" type="file" accept="audio/*"><label class="fieldlabel">Âm lượng</label><input id="volume" type="range" min="0" max="1" step=".05" value="0.3" style="width:100%"><button class="draweraction" id="playmusic">✦ Phát / Tạm dừng</button>';openDrawer("Nhạc nền",box);let a=window.miaAudio||(window.miaAudio=new Audio());a.loop=true;a.volume=+(localStorage.musicVolume||.3);$("#volume").value=a.volume;$("#musicName").textContent=localStorage.musicName||"[Tệp Nhạc]";$("#audiofile").onchange=e=>{if(e.target.files[0]){let f=e.target.files[0];localStorage.musicName=f.name;$("#musicName").textContent=f.name;a.src=URL.createObjectURL(f);musicStore("put",f).catch(()=>{});a.play().catch(()=>toast("Nhấn Phát để nghe nhạc"))}};musicStore("get").then(blob=>{if(!a.src)a.src=blob?URL.createObjectURL(blob):"/track-maker-audio"}).catch(()=>{if(!a.src)a.src="/track-maker-audio"});$("#volume").oninput=e=>{a.volume=+e.target.value;localStorage.musicVolume=a.volume};$("#playmusic").onclick=()=>a.paused?a.play().catch(()=>toast("Không phát được file này")):a.pause()}
function about(){let box=document.createElement("div");box.className="about-view";box.innerHTML='<div class="about-hero"><div class="about-emblem"><img src="/Hizi.png" alt="Mia"></div><div class="about-kicker">YOUR CREATIVE AI SPACE</div><h2>Mia AI</h2><p>Một góc nhỏ để trò chuyện, học hỏi và sáng tạo.</p></div><div class="about-creator"><div class="about-label">NGƯỜI SÁNG TẠO</div><strong>Nina</strong><div class="about-socials"><a href="https://www.tiktok.com/@ninavtokervietnam" target="_blank" rel="noopener noreferrer"><span>TikTok Việt Nam</span><b>@ninavtokervietnam</b></a><a href="https://www.tiktok.com/@nina_vtoker_nihon" target="_blank" rel="noopener noreferrer"><span>TikTok Nhật Bản</span><b>@nina_vtoker_nihon</b></a></div></div><div class="about-version"><div><span class="about-label">MÔ HÌNH</span><strong>Mia 5.6 Beta</strong><small>EXPERIMENT</small></div><div><span class="about-label">GIAO DIỆN</span><strong>V2.4</strong></div><div><span class="about-label">PHIÊN CẬP NHẬT</span><strong>#54</strong></div></div><div class="about-presence"><span class="presence-pulse"></span><div><strong id="miaOnlineCount">Đang kiểm tra…</strong><small>Phiên truy cập đang hoạt động</small></div><span class="presence-live">LIVE</span></div><p class="about-footnote">Số phiên được ước tính theo địa chỉ IP đang hoạt động trong khoảng 90 giây gần nhất.</p>';openDrawer("Về Mia",box);updateOnlineStats()}
function renderAccountAvatar(){const b=$("#accountBtn");if(!b)return;if(me&&!me.guest&&me.avatar){b.innerHTML='<img alt="" src="'+me.avatar.replace(/"/g,"&quot;")+'">';b.classList.add("has-image")}else{b.classList.remove("has-image");b.textContent=me&&!me.guest?(me.username||me.email||"M").trim().charAt(0).toUpperCase():"∅"}}
function account(){let box=document.createElement("div");if(me&&!me.guest){box.innerHTML='<div class="profile-card"><div class="profile-avatar-wrap"><div class="profile-avatar" id="profileAvatar"></div><label class="avatar-edit" for="avatarFile" title="Đổi ảnh đại diện">✎</label><input id="avatarFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden></div><div class="profile-name" id="profileName"></div><div class="profile-email" id="profileEmail"></div></div><label class="fieldlabel" for="profileUsername">Tên hiển thị</label><input class="field" id="profileUsername" maxlength="40" autocomplete="nickname"><button class="primary" id="saveProfile">Lưu thay đổi</button><button class="draweraction" id="logout" style="margin-top:12px">Đăng xuất</button>';openDrawer("Tài khoản",box);box.querySelector("#profileName").textContent=me.username||"Người dùng";box.querySelector("#profileEmail").textContent=me.email||"";box.querySelector("#profileUsername").value=me.username||"";const av=box.querySelector("#profileAvatar");if(me.avatar){av.innerHTML='<img alt="Ảnh đại diện" src="'+me.avatar.replace(/"/g,"&quot;")+'">'}else av.textContent=(me.username||"M").charAt(0).toUpperCase();box.querySelector("#avatarFile").onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2*1024*1024){toast("Ảnh đại diện tối đa 2 MB.");e.target.value="";return}const reader=new FileReader();reader.onload=async()=>{try{const d=await api("/auth/profile",{method:"PATCH",body:JSON.stringify({avatar:reader.result})});me=d.user;renderAccountAvatar();account();toast("Đã cập nhật ảnh đại diện.")}catch(err){toast(err.message)}};reader.readAsDataURL(f)};box.querySelector("#saveProfile").onclick=async()=>{try{const username=box.querySelector("#profileUsername").value.trim();if(!username)return toast("Tên hiển thị không được để trống.");const d=await api("/auth/profile",{method:"PATCH",body:JSON.stringify({username})});me=d.user;renderAccountAvatar();account();toast("Đã lưu thông tin tài khoản.")}catch(e){toast(e.message)}};box.querySelector("#logout").onclick=async()=>{try{await api("/auth/logout",{method:"POST"});location.reload()}catch(e){toast(e.message)}};return}
const loginView=()=>{box.innerHTML='<div class="auth-intro"><div class="auth-mark">M</div><h2>Chào mừng trở lại</h2><p>Đăng nhập để tiếp tục đồng bộ cuộc trò chuyện.</p></div><label class="fieldlabel">Email</label><input class="field" id="email" type="email" autocomplete="email" placeholder="you@example.com"><label class="fieldlabel">Mật khẩu</label><input class="field" id="password" type="password" autocomplete="current-password" placeholder="Mật khẩu"><button class="primary auth-submit" id="login">Đăng nhập</button><div class="auth-divider"><span>HOẶC</span></div><div id="googleSignin" class="google-slot"></div><p id="googleHint" class="mutedtext auth-hint"></p><p class="auth-switch">Bạn chưa có tài khoản? <button id="showRegister">Đăng kí</button></p>';openDrawer("Đăng nhập",box);box.querySelector("#login").onclick=authLogin;box.querySelector("#password").onkeydown=e=>{if(e.key==="Enter")authLogin()};box.querySelector("#showRegister").onclick=registerView;setupGoogleButton(box)};
const registerView=()=>{box.innerHTML='<div class="auth-intro"><div class="auth-mark">M</div><h2>Tạo tài khoản Mia</h2><p>Chỉ mất một chút để bắt đầu đồng bộ dữ liệu.</p></div><label class="fieldlabel">Tên người dùng <span class="required">*</span></label><input class="field" id="username" maxlength="40" autocomplete="nickname" placeholder="Tên mọi người sẽ nhìn thấy"><label class="fieldlabel">Email</label><input class="field" id="email" type="email" autocomplete="email" placeholder="you@example.com"><label class="fieldlabel">Mật khẩu</label><input class="field" id="password" type="password" autocomplete="new-password" placeholder="Ít nhất 8 ký tự"><button class="primary auth-submit" id="register">Tạo tài khoản</button><p class="auth-switch">Đã có tài khoản? <button id="showLogin">Đăng nhập</button></p>';openDrawer("Đăng kí",box);box.querySelector("#register").onclick=authRegister;box.querySelector("#showLogin").onclick=loginView;box.querySelector("#password").onkeydown=e=>{if(e.key==="Enter")authRegister()}};loginView()}
async function setupGoogleButton(box){const hint=box.querySelector("#googleHint"),slot=box.querySelector("#googleSignin");try{const cfg=await api("/config");if(!cfg.googleClientId){hint.textContent="Đăng nhập Google sẽ khả dụng sau khi cấu hình GOOGLE_CLIENT_ID.";return}if(!window.google?.accounts?.id){await new Promise((resolve,reject)=>{let script=document.getElementById("google-identity-script");if(!script){script=document.createElement("script");script.id="google-identity-script";script.src="https://accounts.google.com/gsi/client";script.async=true;script.defer=true;document.head.append(script)}script.addEventListener("load",resolve,{once:true});script.addEventListener("error",reject,{once:true});if(window.google?.accounts?.id)resolve()})}if(!box.isConnected)return;window.google.accounts.id.initialize({client_id:cfg.googleClientId,callback:handleGoogleCredential,ux_mode:"popup",use_fedcm_for_button:false,auto_select:false});window.google.accounts.id.renderButton(slot,{type:"standard",theme:"outline",size:"large",shape:"pill",text:"continue_with",width:280});hint.textContent="Dùng tài khoản Google để đăng nhập nhanh."}catch(e){hint.textContent="Không tải được đăng nhập Google. Thử tải lại trang nhé."}}
async function handleGoogleCredential(response){try{if(!response?.credential)throw Error("Google không trả về thông tin xác thực.");const d=await api("/auth/google",{method:"POST",body:JSON.stringify({credential:response.credential})});me=d.user;renderAccountAvatar();await migrateGuest();await refreshHistory();toast("Đăng nhập Google thành công");account()}catch(e){toast(e.message||"Đăng nhập Google thất bại.")}}
async function authLogin(){try{let d=await api("/auth/login",{method:"POST",body:JSON.stringify({email:$("#email").value,password:$("#password").value})});me=d.user;renderAccountAvatar();await migrateGuest();toast("Đăng nhập thành công");await refreshHistory();account()}catch(e){toast(e.message)}}
async function authRegister(){try{let d=await api("/auth/register",{method:"POST",body:JSON.stringify({email:$("#email").value,password:$("#password").value,username:$("#username").value})});me=d.user;renderAccountAvatar();await migrateGuest();await refreshHistory();toast("Tạo tài khoản thành công");account()}catch(e){toast(e.message)}}
async function migrateGuest(){const old=guestLoad();if(!old.length)return;let count=0;for(let i=0;i<old.length;i++){try{const d=await api("/conversations/import",{method:"POST",body:JSON.stringify({conversations:[old[i]]})});count+=d.imported||0}catch(e){toast("Chưa nhập được toàn bộ lịch sử. Bản gốc vẫn được giữ trên thiết bị.");return}}localStorage.removeItem(localKey);toast(count?"Đã chuyển "+count+" cuộc trò chuyện lên tài khoản.":"Không có lịch sử để chuyển.")}
async function refreshHistory(){if(me&&!me.guest){try{let d=await api("/conversations");history=d.conversations||[]}catch{history=[]}}else history=guestLoad()}
function markdown(raw){let s=String(raw||"");const esc=x=>String(x).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));const safe=x=>{try{let u=new URL(x);return u.protocol==="http:"||u.protocol==="https:"?u.href:null}catch{return null}};const links=[];s=s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,label,url)=>{let href=safe(url);if(!href)return label;let k="@@LINK"+links.length+"@@";links.push('<a href="'+esc(href)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>');return k});s=esc(s).replace(/\*\*(.*?)\*\*/g,"<strong>$1</strong>").replace(/\*(.*?)\*/g,"<em>$1</em>").replace(/`([^`]+)`/g,"<code>$1</code>").replace(/(https?:\/\/[^\s&lt;]+)/g,rawurl=>{let href=safe(rawurl.replace(/&amp;/g,"&"));return href?'<a href="'+esc(href)+'" target="_blank" rel="noopener noreferrer">'+esc(rawurl)+'</a>':rawurl});s=s.replace(/@@LINK(\d+)@@/g,(_,i)=>links[+i]);return s.split("\n").map(x=>x.trim()?'<p>'+x+'</p>':'').join("")}
function addMessage(role,content,media){$("#welcome").style.display="none";let row=document.createElement("div");row.className="message "+role;if(role==="assistant"){let icon=document.createElement("div");icon.className="roleicon";icon.innerHTML='<img src="/Hizi.png" alt="Mia">';row.append(icon)}let b=document.createElement("div");b.className="bubble";if(role==="assistant")b.innerHTML=markdown(content||"");else{b.textContent=content||"";if(media){(Array.isArray(media)?media:[media]).forEach(m=>{if(!m?.dataUrl)return;let el=m.type?.startsWith("video/")?document.createElement("video"):document.createElement("img");el.src=m.dataUrl;el.style.display="block";el.style.maxWidth="min(320px,75vw)";el.style.maxHeight="280px";el.style.marginTop="8px";el.style.borderRadius="12px";if(el.tagName==="VIDEO"){el.controls=true;el.playsInline=true}else{el.style.cursor="zoom-in";el.onclick=()=>showMedia(m)}b.append(el)})}}row.append(b);messagesEl.append(row);chatEl.scrollTop=chatEl.scrollHeight}
async function loadConversation(cid){messagesEl.innerHTML="";let c;if(me&&!me.guest){try{c=(await api("/conversations/"+cid)).conversation}catch(e){const local=guestLoad().find(x=>x.id===cid);if(local){try{await api("/conversations/import",{method:"POST",body:JSON.stringify({conversations:[local]})});await refreshHistory();c=history.find(x=>x.id===cid)}catch(err){toast("Không mở được chat cũ: "+err.message);return}}else{toast("Chat này không thuộc tài khoản hiện tại hoặc đã bị xóa.");return}}}else c=history.find(x=>x.id===cid);if(!c){toast("Không tìm thấy cuộc trò chuyện.");return}currentId=c.id;$("#welcome").style.display="none";(c.messages||[]).forEach(m=>addMessage(m.role,m.content,m.media));closeDrawer()}
function saveLocal(){guestSave()}
async function submit(){let text=input.value.trim();if((!text&&!attached.length)||busy)return;busy=true;send.disabled=true;input.value="";resize();let media=attached.slice();attached=[];renderPreviews();let c;try{if(!currentId){let made=await api("/conversations",{method:"POST",body:"{}"});currentId=made.conversation.id;c=made.conversation;if(!me||me.guest){c.messages=[];history.unshift(c)}}c=c||localConversation();addMessage("user",text,media);c.messages=c.messages||[];c.messages.push({role:"user",content:text,media,createdAt:Date.now()});if(c.title==="Cuộc trò chuyện mới"||c.title==="Cuộc trò chuyện"){c.title=(text||"Tệp đính kèm").slice(0,48)}c.updatedAt=Date.now();if(!me||me.guest)saveLocal();let typing=document.createElement("div");typing.className="typing";typing.textContent="Mia đang nghĩ…";messagesEl.append(typing);chatEl.scrollTop=chatEl.scrollHeight;let d=await api("/chat",{method:"POST",body:JSON.stringify({conversationId:currentId,message:text,media})});typing.remove();addMessage("assistant",d.answer);c.messages.push({role:"assistant",content:d.answer,createdAt:Date.now()});c.updatedAt=Date.now();if(!me||me.guest)saveLocal();else await refreshHistory()}catch(e){let t=document.querySelector(".typing");if(t)t.remove();addMessage("assistant","Mình gặp lỗi: "+e.message);toast(e.message)}finally{busy=false;send.disabled=false;input.focus()}}
send.onclick=submit;function positionAttachMenu(){const menu=$("#attachMenu"),btn=$("#attachBtn"),r=btn.getBoundingClientRect();menu.style.left=Math.max(12,Math.min(r.left,window.innerWidth-312))+"px";menu.style.bottom=Math.max(12,window.innerHeight-r.top+10)+"px";menu.style.top="auto"}
function toggleAttachMenu(){const menu=$("#attachMenu"),opening=!menu.classList.contains("show");menu.classList.toggle("show",opening);if(opening)positionAttachMenu()}
$("#attachBtn").onclick=e=>{e.stopPropagation();toggleAttachMenu()};
window.addEventListener("resize",()=>{if($("#attachMenu").classList.contains("show"))positionAttachMenu()});$("#pickImage").onclick=()=>{$("#attachMenu").classList.remove("show");$("#file").click()};$("#pickFile").onclick=()=>{$("#attachMenu").classList.remove("show");$("#anyfile").click()};$("#pickCamera").onclick=()=>{$("#attachMenu").classList.remove("show");$("#camera").click()};$("#pickPlugin").onclick=()=>toast("Plugin: ĐANG CẬP NHẬT");$("#thinkToggle").onclick=e=>{e.currentTarget.classList.toggle("selected");toast(e.currentTarget.classList.contains("selected")?"Đã bật Suy nghĩ kỹ hơn":"Đã tắt Suy nghĩ kỹ hơn")};document.addEventListener("click",e=>{if(!e.target.closest(".tools"))$("#attachMenu").classList.remove("show")});function addFiles(files){for(const f of files){if(attached.length>=3){toast("Tối đa 3 tệp");break}if(!f.type.startsWith("image/")&&!f.type.startsWith("video/")){toast("Chọn ảnh hoặc video");continue}if(attached.reduce((n,x)=>n+x.size,0)+f.size>15*1024*1024){toast("Tổng tệp tối đa 15 MB");break}let rd=new FileReader();rd.onload=()=>{attached.push({type:f.type,name:f.name,dataUrl:rd.result,size:f.size});renderPreviews()};rd.readAsDataURL(f)}}function renderPreviews(){let p=$("#filelabel");p.innerHTML="";attached.forEach((m,i)=>{let w=document.createElement("span");w.className="attachment-preview";let el=m.type.startsWith("video/")?document.createElement("video"):document.createElement("img");el.src=m.dataUrl;if(el.tagName==="VIDEO")el.muted=true;el.onclick=()=>showMedia(m);let x=document.createElement("button");x.textContent="×";x.onclick=()=>{attached.splice(i,1);renderPreviews()};w.append(el,x);p.append(w)})}function showMedia(m){let o=document.createElement("div");o.className="media-lightbox";let el=m.type.startsWith("video/")?document.createElement("video"):document.createElement("img");el.src=m.dataUrl;if(el.tagName==="VIDEO")el.controls=true;let d=document.createElement("a");d.href=m.dataUrl;d.download=m.name||"mia-media";d.textContent="Tải xuống";let x=document.createElement("button");x.textContent="×";x.onclick=()=>o.remove();o.append(x,el,d);o.onclick=e=>{if(e.target===o)o.remove()};document.body.append(o)}$("#file").onchange=e=>{addFiles(e.target.files);e.target.value=""};$("#camera").onchange=e=>{addFiles(e.target.files);e.target.value=""};$("#anyfile").onchange=e=>{addFiles(e.target.files);e.target.value=""};input.addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();submit()}});function resize(){input.style.height="auto";input.style.height=Math.min(input.scrollHeight,180)+"px"}input.addEventListener("input",resize);

document.querySelectorAll("[data-prompt]").forEach(b=>b.onclick=()=>{input.value=b.dataset.prompt;resize();input.focus()});
let onlineStatsTimer=null;async function updateOnlineStats(){try{const d=await api("/stats/online"),el=$("#miaOnlineCount");if(el)el.textContent=Number(d.online||0).toLocaleString("vi-VN")+" phiên";return d.online}catch(e){const el=$("#miaOnlineCount");if(el)el.textContent="Chưa có dữ liệu";return null}}function startOnlinePresence(){updateOnlineStats();if(onlineStatsTimer)clearInterval(onlineStatsTimer);onlineStatsTimer=setInterval(updateOnlineStats,40000)}
async function initBackgroundMusic(){let a=window.miaAudio||(window.miaAudio=new Audio());a.loop=true;a.volume=+(localStorage.musicVolume||.3);try{let blob=await musicStore("get");a.src=blob?URL.createObjectURL(blob):"/track-maker-audio"}catch{a.src="/track-maker-audio"}a.play().catch(()=>{document.addEventListener("pointerdown",()=>a.play().catch(()=>{}),{once:true});document.addEventListener("keydown",()=>a.play().catch(()=>{}),{once:true})})}
